import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { Icon } from '@/design-system/Icon'
import { Field } from '@/components/ui'
import { useI18n } from '@/i18n'
import { useSession } from '@/app/session'
import { moduleLinksFor, otherModulesFor, type ModuleLink } from '@/app/nav'

/**
 * Every module in the app, on its own tab.
 *
 * This exists because the previous arrangement hid fifteen features behind a
 * screen called "Kehidupan" that mostly showed chores — so the honest reading
 * was that the app had five features. A directory that admits to being a
 * directory is better than a screen that quietly doubles as one.
 *
 * Stage decides the ORDER here, never what is present.
 */
export default function AllModules() {
  const { t } = useI18n()
  const { profile } = useSession()
  const [q, setQ] = useState('')

  const stage = profile?.stage ?? 'married'
  const suggested = useMemo(() => moduleLinksFor(stage), [stage])
  const others = useMemo(() => otherModulesFor(stage), [stage])

  const match = (m: ModuleLink) =>
    !q.trim() ||
    t(m.label).toLowerCase().includes(q.toLowerCase()) ||
    t(m.desc).toLowerCase().includes(q.toLowerCase())

  const hitsA = suggested.filter(match)
  const hitsB = others.filter(match)
  const nothing = hitsA.length === 0 && hitsB.length === 0

  return (
    <div className="stack">
      <h1>{t('nav.all')}</h1>
      <p className="card__hint">{t('mod.allHint')}</p>

      <Field label={t('mod.search')}>
        {(p) => (
          <input
            {...p}
            type="search"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder={t('mod.searchPlaceholder')}
          />
        )}
      </Field>

      {nothing && <p className="card__hint">{t('mod.noMatch')}</p>}

      {hitsA.length > 0 && (
        <>
          <p className="modgroup">{t('mod.suggested')}</p>
          <Grid links={hitsA} />
        </>
      )}
      {hitsB.length > 0 && (
        <>
          <p className="modgroup">{t('mod.others')}</p>
          <Grid links={hitsB} />
        </>
      )}
    </div>
  )
}

function Grid({ links }: { links: ModuleLink[] }) {
  const { t } = useI18n()
  return (
    <div className="modgrid">
      {links.map((m) => (
        <Link key={m.to} to={m.to} className="modcard">
          <span className="modcard__ic">
            <Icon name={m.icon} size={22} />
          </span>
          <span className="modcard__body">
            <strong>{t(m.label)}</strong>
            <small>{t(m.desc)}</small>
          </span>
          <Icon name="chevron-right" size={16} className="modcard__go" />
        </Link>
      ))}
    </div>
  )
}
